#define rotation 2

precision highp float;

#define resolution iResolution.xy
#define time iTime

// stuff
#define rot( a )	mat2( cos(a), -sin(a), sin(a), cos(a) )

#define nsin( a )       sin( a )*.5+.5

float c = 0.0;

float circle( vec2 p, float r )
{
	return step( length( p ), r);
}



//#define A(u,w) 	k=length(p.xy);p.x=k*(sin(mod(atan(p.y,p.x),3.14))*(sin(p.x))-1.)/u;p.y=k-w		
#define A(u,w) 	k=length(p3.xy);p3.x=k*(mod(atan(p3.y,p3.x),2.*3.14/u)-3.14/u);p3.y=k-w		
#define B(u,w) 	k=length(p3.yz);p3.y=k*(mod(atan(p3.z,p3.y),2.*3.14/u)-3.14/u);p3.z=k-w		


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 1. Normalize pixel coords so that (0,0) is screen center,
    //    and the smaller dimension is 1.0 unit.
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec2 p;
    float zoom = cos(iTime)*4.;
    p = zoom*( 2.*gl_FragCoord.xy - resolution )/min( resolution.x, resolution.y );

    #if ( rotation == 1 )	
    p *= rot( time*1. );
    #endif

	vec3 rd = normalize(vec3(uv, 1)), q = vec3(0,0, -280.), p3; 
	vec4 Fr = vec4(0);
	for (float i = 1.; i < 70.; i++) {
		float k;
		p3=q;
		p3.yz *= rot(time); 
		p3.xz *= rot(time); 

		A(8.,0.);
		B(12.,48.);
		A(4.*(1.+cos(time/4.)),2.);
		B(22.,25.*min(1.,pow(min(2.,mod(time-1.3,6.)),8.)));
		float d = abs(p3.x)+abs(p3.y)+abs(p3.z)-length(p3)-1.; 
		if (d < 0.1) {
			if(abs(p3.z)<5.+320.*pow(min(2.,mod(time,6.))-1.,8.)) 

            Fr = vec4(length(p)/18., 500./i/max(1.,50.),atan(abs(p3.y/p3.z)),1);			
			break;
		}
		q += rd * d;
	}
    float dist = sqrt( floor( cos(iTime) *15. )/2. + .5 );	

    float l = sqrt( 3. )/dist;
    float s =     ( 1. )/dist;
    float n =     ( 2. )/dist;

    // well i guess here comes the hardcoded stuff
    c = circle( p, 1.0 );
    p.x -= l;
    p.y -= s;
    c += circle( p, 1.0 );
    p.x += l;
    p.y -= s;
    c += circle( p, 1.0 );
    p.x += l;
    p.y += s;
    c += circle( p, 1.0 );
    p.x -= 0.;
    p.y += n;
    c += circle( p, 1.0 );
    p.x -= l;
    p.y += s;
    c += circle( p, 1.0 );
    p.x -= l;
    p.y -= s;
    c += circle( p, 1.0 );

    // white + white = black
    c = mod( c, 2.0 );

    // 2. Time variable
    float t = iTime;

    // 3. Convert to polar coordinates
    float r = length(uv);
    float a = atan(uv.y, uv.x);

    // 4. Define how many times we want to repeat around the circle (symmetry)
    //    For Nasir al-Mulk–style patterns, 8, 12, 16, etc. can look interesting.
    float k = 1.0;

    // 5. "Fold" the angle so the pattern repeats k times around the center
    //    We do this by restricting a to one slice, then reflecting it back out
    //    to the original [0, 2π) range.
    a = fract(a / (2.0 * 3.14159 / k)) * (2.0 * 3.14159 / k);

    // 6. Add a small radial ripple distortion (like folding/rippling).
    //    The ripple’s "phase" can use time, so it moves or pulses.
    float rippleFreq = 53.0;   // how many ripple waves outward
    float rippleAmp  = 0.2;   // amplitude of the ripple
    float ripple = sin(r * rippleFreq - t * 2.0) * rippleAmp;
    r += ripple;

    // 7. Convert back to Cartesian
    vec2 pos = vec2( r * cos(a), r * sin(a) );

    // 8. Start building a color. We can sample a fractal-like function or
    //    combine trig waveforms. Let’s do some wave layering for color.
    float wave = sin(pos.x * 5.0 + pos.y * 5.0 + t * 2.0)
               + 0.5 * sin(pos.x * 10.0 - pos.y * 10.0 - t * 3.0);

    // Remap wave from [-1,1] to [0,1]
    float w = 0.5 + 0.5 * wave;

    // 9. Construct a color from w, layering phases.
    //    We'll shift phases for each channel a bit
    vec3 color = vec3(
        sin(w * 6.28 + 0.0),
        sin(w * 6.28 + 2.0),
        sin(w * 6.28 + 4.0)
    );
    color = 0.5 + 0.5 * color; // keep color within [0..1]

    // 10. Gradually fade color towards black as we move away from the center
    color *= 1.0 - 0.8 * r;  // adjust fade strength to taste

    // 11. Output final color
    fragColor = vec4(color*Fr.xyz, 1.0);

    fragColor*= vec4(c, c, c, 1.0);
}
